using System;using System.Linq;using System.Collections.Generic;using BeamScheduleFormatter;
class CommercialBarsTests {
 static int checks;static void Check(bool x,string message){if(!x)throw new Exception(message);checks++;}
 static void Main(){
 int[] sizes={10,12,16,20,25,28,32,36,40,50};double[] masses={.617,.888,1.578,2.466,3.853,4.834,6.313,7.990,9.865,15.41};for(int n=0;n<sizes.Length;n++)Check(EstimatorEngine.UnitMass(sizes[n])==masses[n],"Nominal mass mismatch");
 var limited=CommercialBars.Choices(4,3,0,new[]{6.0});Check(limited.Count==1&&limited[0].Length==6,"Unselected stock length used");Check(CommercialBars.ParseLengths("6,12").SequenceEqual(new[]{6.0,12.0}),"Stock option restore");bool noStock=false;try{CommercialBars.Available(new double[0]);}catch(ArgumentException){noStock=true;}Check(noStock,"Empty stock selection allowed");
 var c=CommercialBars.Best(CommercialBars.Choices(2.4,10));Check(c.Length==12&&c.Bars==2&&c.Waste<1e-9,"Exact stock choice");
 c=CommercialBars.Best(CommercialBars.Choices(3.1,3));Check(c.Length==10.5&&c.Bars==1,"Total quantity waste selection");
 foreach(double cut in new[]{.175,1.5,2.99999999,3.00000001,5.1,6.0,11.9,12.0})foreach(long qty in new long[]{1,3,11,100000}){var choices=CommercialBars.Choices(cut,qty);var best=CommercialBars.Best(choices);foreach(var x in choices){Check(x.PiecesPerStock*cut<=x.Length,"Piece exceeds stock");Check(x.Bars*x.PiecesPerStock>=qty,"Insufficient pieces");Check((x.Bars-1)*x.PiecesPerStock<qty,"Excess stock count");Check(x.Waste>=0&&best.Waste<=x.Waste+1e-8,"Minimum waste violated");}}
 var shortSplice=CommercialBars.Choices(8,2,.8).Single(x=>x.Length==6);Check(shortSplice.Segments==2&&shortSplice.Bars==4,"Splice on shorter commercial stock missing");
 foreach(double stock in CommercialBars.Lengths){var option=CommercialBars.Choices(25,4,.8).Single(x=>x.Length==stock);Check(option.SegmentCut<=stock,"Spliced cut exceeds stock");Check(option.Bars==option.Segments*4,"Spliced stock quantity");Check(Math.Abs(option.Used-(100+option.SpliceMetres))<1e-8,"Lap steel missing");Check(Math.Abs(option.Purchased-option.Used-option.Waste)<1e-8,"Stock balance");}
 Check(CommercialBars.Choices(15.0000001,3).Count==0,"Oversize cut fitted");
 Check(CommercialBars.ParseLengths("13.5,15").SequenceEqual(new[]{13.5,15}),"Extended stock options restore");Check(CommercialBars.Choices(14.8,2,0,new[]{15.0}).Single().Segments==1,"15m stock avoids an unnecessary splice");Check(CommercialBars.Choices(13.5,1,0,new[]{13.5}).Single().Waste==0,"13.5m exact fit");var input=new EstimateInput{Quantity="3",Result=new BeamEstimate()};input.Result.Lines.Add(new EstimateLine{Part="Top CONTINUOUS",Grade=60,Diameter=16,PiecesPerBeam=2,CutLength=5});input.Result.Lines.Add(new EstimateLine{Part="Side-face",Grade=40,Diameter=12,PiecesPerBeam=4,CutLength=5});input.Result.Lines.Add(new EstimateLine{Part="Stirrups",Grade=40,Diameter=10,TieSetsPerBeam=20,MainHoopCut=1.8,AdditionalLegCut=.5,AdditionalLegs=2});
 var demands=CommercialBars.Demands(new[]{input});Check(demands.Single(d=>d.Diameter==16).Pieces==6,"Beam quantity multiplied incorrectly");Check(demands.Single(d=>d.Diameter==12).Pieces==12,"EF/SFR quantity");Check(demands.Single(d=>d.Cut==1.8).Pieces==60,"Hoop pieces");Check(demands.Single(d=>d.Cut==.5).Pieces==120,"Additional leg pieces");
 var one=new EstimateInput{Quantity="1",Result=new BeamEstimate()};one.Result.Lines.Add(new EstimateLine{Part="Top CONTINUOUS",Grade=60,Diameter=16,PiecesPerBeam=1,CutLength=2.4});var two=new EstimateInput{Quantity="3",Result=new BeamEstimate()};two.Result.Lines.Add(new EstimateLine{Part="Bottom CONTINUOUS",Grade=60,Diameter=16,PiecesPerBeam=1,CutLength=2.4});var allocation=CommercialBars.Allocate(new[]{one,two},null);var pooled=CommercialBars.Best(CommercialBars.Choices(2.4,4));Check(Math.Abs(allocation.Sum(x=>x.Purchase)-pooled.Purchased*1.578)<1e-9,"Entry purchase does not reconcile with stock");Check(Math.Abs(allocation[1].Purchase-3*allocation[0].Purchase)<1e-9,"Shared stock allocation ratio");Check(allocation.All(x=>Math.Abs(x.Net+x.Splice+x.Waste-x.Purchase)<1e-9),"Allocated purchase balance");Check(allocation.Sum(x=>x.Choice.Bars)>pooled.Bars,"Shared stock test fixture invalid");
 var summary=new System.Text.StringBuilder();typeof(EstimatorForm).GetMethod("AppendPurchaseSummary",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{summary,allocation});Check(summary.ToString().Contains("SELECTED COMMERCIAL BARS TO ORDER"),"Purchase order summary missing");Check(summary.ToString().Contains(string.Format(System.Globalization.CultureInfo.InvariantCulture,"{0,-8}{1,6}{2,13:0.00}{3,13}{4,16:0.00}","G60","Ø16",pooled.Length,pooled.Bars,pooled.Purchased*1.578)),"Pooled stock bars counted more than once in report");
 Check(CommercialBars.Report(new[]{input}).Contains("GRADE 60"),"Grade summary missing");EstimateInput offcutA=new EstimateInput{Quantity="1",Result=new BeamEstimate()},offcutB=new EstimateInput{Quantity="1",Result=new BeamEstimate()};offcutA.Result.Lines.Add(new EstimateLine{Part="Top",Grade=60,Diameter=16,PiecesPerBeam=1,CutLength=3.5});offcutB.Result.Lines.Add(new EstimateLine{Part="Bottom",Grade=60,Diameter=16,PiecesPerBeam=1,CutLength=2.5});var mixed=CommercialBars.Allocate(new[]{offcutA,offcutB},null,new[]{6.0});Check(mixed.SelectMany(a=>a.Stocks).Distinct().Sum(b=>b.Count)==1,"Different-cut offcut was not reused");Check(Math.Abs(mixed.Sum(a=>a.Waste))<1e-9,"Exact mixed cuts retain waste");Check(Math.Abs(mixed.Sum(a=>a.Purchase)-6*1.578)<1e-9,"Mixed-cut mass balance");offcutB.Result.Lines[0].Grade=40;mixed=CommercialBars.Allocate(new[]{offcutA,offcutB},null,new[]{6.0});Check(mixed.SelectMany(a=>a.Stocks).Distinct().Sum(b=>b.Count)==2,"Different grades share stock");offcutB.Result.Lines[0].Grade=60;offcutB.Result.Lines[0].Diameter=12;mixed=CommercialBars.Allocate(new[]{offcutA,offcutB},null,new[]{6.0});Check(mixed.SelectMany(a=>a.Stocks).Distinct().Sum(b=>b.Count)==2,"Different diameters share stock");offcutB.Result.Lines[0].Diameter=16;var separate=CommercialBars.Allocate(new[]{offcutA},null,new[]{6.0}).Concat(CommercialBars.Allocate(new[]{offcutB},null,new[]{9.0})).ToList();RebarOffcuts.Allocate(separate);Check(separate.SelectMany(a=>a.Stocks).Distinct().Sum(b=>b.Count)==2,"A category used unchecked stock");
var bulk=new EstimateInput{Quantity="100000",Result=new BeamEstimate()};bulk.Result.Lines.Add(new EstimateLine{Part="Top",Grade=60,Diameter=16,PiecesPerBeam=1000,CutLength=3.5});bulk.Result.Lines.Add(new EstimateLine{Part="Bottom",Grade=60,Diameter=16,PiecesPerBeam=1000,CutLength=2.5});mixed=CommercialBars.Allocate(new[]{bulk},null,new[]{6.0});Check(mixed.SelectMany(a=>a.Stocks).Distinct().Sum(b=>b.Count)==100000000,"Bulk patterns lost cuts");Check(mixed.SelectMany(a=>a.Stocks).Distinct().Count()==1,"Bulk allocation expanded every piece");Check(mixed.All(a=>Math.Abs(a.Purchase-a.Net-a.Splice-a.Waste)<1e-5),"Bulk mass balance failed");
Console.WriteLine("PASS: "+checks+" commercial stock fit, quantity, minimum-waste and component checks.");
 }
}
